use xiom.io;

use xiom.string;
type Document = {
  content: Str;
  word_count: Int;
  invariant: word_count >= 0;
}

fn consume_document(doc: Document) -> Str
  requires: doc.word_count > 0;
{
  return doc.content;
}

fn read_document(doc: &Document) -> Str {
  return doc.content;
}

fn edit_document(doc: &mut Document, new_text: Str)
  requires: string.str_len(new_text) > 0;
{
  doc.content = new_text;
  doc.word_count = string.str_len(new_text);
}

fn clone_document(doc: &Document) -> Document {
  return Document{ content: doc.content, word_count: doc.word_count };
}

fn main() -> Int {
  var original: Document = Document{ content: "Hello XIOM", word_count: 2 };
  let content = read_document(&original);
  edit_document(&mut original, "Hello Safe World");
  let copy = clone_document(&original);
  let consumed_content = consume_document(copy);
  return original.word_count;
}
